import React, { useState } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Typography,
  Box,
  Card,
  CardContent,
  Grid,
  Tabs,
  Tab
} from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutlined';
import CancelOutlinedIcon from '@mui/icons-material/CancelOutlined';

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`cricket-stats-tabpanel-${index}`}
      aria-labelledby={`cricket-stats-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ pt: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

function StatsTable({ games }) {
  const [activeTab, setActiveTab] = useState(0);

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  // --- BATTING CALCULATIONS ---
  const totalMatches = games.length;
  const totalRuns = games.reduce((sum, g) => sum + (g.runs_scored || 0), 0);
  const highestScore = games.length > 0 ? Math.max(...games.map(g => g.runs_scored || 0)) : 0;
  const timesOut = games.filter(g => g.is_out).length;
  const battingAverage = timesOut > 0 ? (totalRuns / timesOut).toFixed(2) : 'N/A';

  // --- BOWLING CALCULATIONS ---
  const bowlingGames = games.filter(g => (g.overs_bowled || 0) > 0);
  const totalWickets = games.reduce((sum, g) => sum + (g.wickets_taken || 0), 0);
  const totalRunsConceded = games.reduce((sum, g) => sum + (g.runs_conceded || 0), 0);

  // Calculate total balls bowled
  const totalBallsBowled = games.reduce((sum, g) => {
    const overs = g.overs_bowled || 0;
    const balls = (Math.floor(overs) * 6) + Math.round((overs % 1) * 10);
    return sum + balls;
  }, 0);

  const totalOversEquivalent = totalBallsBowled / 6;
  const overallEconomy = totalOversEquivalent > 0 ? (totalRunsConceded / totalOversEquivalent).toFixed(2) : '—';
  const overallBowlingAverage = totalWickets > 0 ? (totalRunsConceded / totalWickets).toFixed(2) : '—';

  // Calculate Best Bowling Performance
  let bestBowling = '—';
  if (bowlingGames.length > 0) {
    let maxWickets = -1;
    let minRuns = Infinity;

    games.forEach(g => {
      const wickets = g.wickets_taken || 0;
      const runs = g.runs_conceded || 0;
      const overs = g.overs_bowled || 0;
      if (overs > 0) {
        if (wickets > maxWickets) {
          maxWickets = wickets;
          minRuns = runs;
        } else if (wickets === maxWickets && runs < minRuns) {
          minRuns = runs;
        }
      }
    });

    if (maxWickets >= 0) {
      bestBowling = `${maxWickets}/${minRuns}`;
    }
  }

  // --- FIELDING CALCULATIONS ---
  const totalCatches = games.reduce((sum, g) => sum + (g.catches || 0), 0);
  const totalRunOuts = games.reduce((sum, g) => sum + (g.run_outs || 0), 0);
  const totalStumpings = games.reduce((sum, g) => sum + (g.stumpings || 0), 0);

  // Helper to calculate statistics for a bowling row
  const getBowlingRowStats = (game) => {
    const overs = game.overs_bowled || 0;
    const runs = game.runs_conceded || 0;
    const wickets = game.wickets_taken || 0;

    if (overs === 0) {
      return { economy: '—', average: '—', strikeRate: '—' };
    }

    const balls = (Math.floor(overs) * 6) + Math.round((overs % 1) * 10);
    const oversEquivalent = balls / 6;

    const economy = oversEquivalent > 0 ? (runs / oversEquivalent).toFixed(2) : '—';
    const average = wickets > 0 ? (runs / wickets).toFixed(2) : '—';
    const strikeRate = wickets > 0 ? (balls / wickets).toFixed(2) : '—';

    return { economy, average, strikeRate };
  };

  return (
    <Box sx={{ width: '100%' }}>
      {/* Dynamic aggregate summaries based on active tab */}
      {activeTab === 0 && (
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Matches Played
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                  {totalMatches}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Total Runs
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'secondary.main' }}>
                  {totalRuns}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Highest Score
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'info.main' }}>
                  {highestScore}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Batting Average
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'warning.main' }}>
                  {battingAverage}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {activeTab === 1 && (
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Total Wickets
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                  {totalWickets}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Overs Bowled
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'secondary.main' }}>
                  {totalOversEquivalent > 0 ? `${Math.floor(totalOversEquivalent)}.${totalBallsBowled % 6}` : '0.0'}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Best Bowling
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'info.main' }}>
                  {bestBowling}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Bowling Economy
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'warning.main' }}>
                  {overallEconomy}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {activeTab === 2 && (
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Total Catches
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                  {totalCatches}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Run Outs
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'secondary.main' }}>
                  {totalRunOuts}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Stumpings
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'info.main' }}>
                  {totalStumpings}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Total Fielding Acts
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 'bold', color: 'warning.main' }}>
                  {totalCatches + totalRunOuts + totalStumpings}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Tabs selector */}
      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 1 }}>
        <Tabs
          value={activeTab}
          onChange={handleTabChange}
          aria-label="cricket stats table tabs"
          textColor="primary"
          indicatorColor="primary"
          variant="fullWidth"
        >
          <Tab label="Batting Scorecard" id="cricket-stats-tab-0" />
          <Tab label="Bowling Scorecard" id="cricket-stats-tab-1" />
          <Tab label="Fielding Scorecard" id="cricket-stats-tab-2" />
        </Tabs>
      </Box>

      {/* Batting Scorecard Tab */}
      <TabPanel value={activeTab} index={0}>
        <TableContainer component={Paper} elevation={3} sx={{ borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
          <Table sx={{ minWidth: 650 }} aria-label="cricket batting table">
            <TableHead sx={{ bgcolor: 'primary.dark' }}>
              <TableRow>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Date</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Club</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Opponent</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Venue</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Runs</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Position</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Status</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Dismissal</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {games.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} align="center" sx={{ py: 6 }}>
                    <Typography variant="body1" color="text.secondary">
                      No game records found. Click "Enter New Game" to add one!
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                games.map((game) => (
                  <TableRow
                    key={game.id}
                    sx={{ '&:last-child td, &:last-child th': { border: 0 }, '&:hover': { bgcolor: 'rgba(255, 255, 255, 0.02)' } }}
                  >
                    <TableCell component="th" scope="row">{game.date}</TableCell>
                    <TableCell>{game.club}</TableCell>
                    <TableCell>{game.opponent}</TableCell>
                    <TableCell>
                      <Chip 
                        label={game.location} 
                        size="small" 
                        color={game.location === 'Home' ? 'primary' : 'default'}
                        variant={game.location === 'Home' ? 'filled' : 'outlined'}
                      />
                    </TableCell>
                    <TableCell align="right" sx={{ fontWeight: 'bold', fontSize: '1.1rem' }}>
                      {game.runs_scored}
                      {!game.is_out && '*'}
                    </TableCell>
                    <TableCell align="right">{game.batting_number}</TableCell>
                    <TableCell>
                      {game.is_out ? (
                        <Chip icon={<CancelOutlinedIcon />} label="Out" size="small" color="error" variant="outlined" />
                      ) : (
                        <Chip icon={<CheckCircleOutlineIcon />} label="Not Out" size="small" color="success" variant="outlined" />
                      )}
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" sx={{ fontStyle: game.dismissal === 'None' ? 'italic' : 'normal', color: game.dismissal === 'None' ? 'text.secondary' : 'text.primary' }}>
                        {game.dismissal}
                      </Typography>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </TabPanel>

      {/* Bowling Scorecard Tab */}
      <TabPanel value={activeTab} index={1}>
        <TableContainer component={Paper} elevation={3} sx={{ borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
          <Table sx={{ minWidth: 650 }} aria-label="cricket bowling table">
            <TableHead sx={{ bgcolor: 'secondary.dark' }}>
              <TableRow>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Date</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Club</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Opponent</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Venue</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Overs</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Maidens</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Runs</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Wickets</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Economy</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Average</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>SR</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {games.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={11} align="center" sx={{ py: 6 }}>
                    <Typography variant="body1" color="text.secondary">
                      No game records found. Click "Enter New Game" to add one!
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                games.map((game) => {
                  const stats = getBowlingRowStats(game);
                  return (
                    <TableRow
                      key={game.id}
                      sx={{ '&:last-child td, &:last-child th': { border: 0 }, '&:hover': { bgcolor: 'rgba(255, 255, 255, 0.02)' } }}
                    >
                      <TableCell component="th" scope="row">{game.date}</TableCell>
                      <TableCell>{game.club}</TableCell>
                      <TableCell>{game.opponent}</TableCell>
                      <TableCell>
                        <Chip 
                          label={game.location} 
                          size="small" 
                          color={game.location === 'Home' ? 'primary' : 'default'}
                          variant={game.location === 'Home' ? 'filled' : 'outlined'}
                        />
                      </TableCell>
                      <TableCell align="right">{(game.overs_bowled || 0).toFixed(1)}</TableCell>
                      <TableCell align="right">{game.maidens_bowled || 0}</TableCell>
                      <TableCell align="right">{game.runs_conceded || 0}</TableCell>
                      <TableCell align="right" sx={{ fontWeight: 'bold', color: 'primary.light' }}>{game.wickets_taken || 0}</TableCell>
                      <TableCell align="right" sx={{ fontWeight: 'bold' }}>{stats.economy}</TableCell>
                      <TableCell align="right">{stats.average}</TableCell>
                      <TableCell align="right">{stats.strikeRate}</TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </TabPanel>

      {/* Fielding Scorecard Tab */}
      <TabPanel value={activeTab} index={2}>
        <TableContainer component={Paper} elevation={3} sx={{ borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)' }}>
          <Table sx={{ minWidth: 650 }} aria-label="cricket fielding table">
            <TableHead sx={{ bgcolor: 'warning.dark' }}>
              <TableRow>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Date</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Club</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Opponent</TableCell>
                <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Venue</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Catches</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Run Outs</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Stumpings</TableCell>
                <TableCell align="right" sx={{ color: 'primary.contrastText', fontWeight: 'bold' }}>Byes Conceded</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {games.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} align="center" sx={{ py: 6 }}>
                    <Typography variant="body1" color="text.secondary">
                      No game records found. Click "Enter New Game" to add one!
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                games.map((game) => (
                  <TableRow
                    key={game.id}
                    sx={{ '&:last-child td, &:last-child th': { border: 0 }, '&:hover': { bgcolor: 'rgba(255, 255, 255, 0.02)' } }}
                  >
                    <TableCell component="th" scope="row">{game.date}</TableCell>
                    <TableCell>{game.club}</TableCell>
                    <TableCell>{game.opponent}</TableCell>
                    <TableCell>
                      <Chip 
                        label={game.location} 
                        size="small" 
                        color={game.location === 'Home' ? 'primary' : 'default'}
                        variant={game.location === 'Home' ? 'filled' : 'outlined'}
                      />
                    </TableCell>
                    <TableCell align="right" sx={{ fontWeight: (game.catches || 0) > 0 ? 'bold' : 'normal' }}>{game.catches || 0}</TableCell>
                    <TableCell align="right" sx={{ fontWeight: (game.run_outs || 0) > 0 ? 'bold' : 'normal' }}>{game.run_outs || 0}</TableCell>
                    <TableCell align="right" sx={{ fontWeight: (game.stumpings || 0) > 0 ? 'bold' : 'normal' }}>{game.stumpings || 0}</TableCell>
                    <TableCell align="right">{game.byes_conceded || 0}</TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </TabPanel>
    </Box>
  );
}

export default StatsTable;
